const STARRED_REPOS_KEY = 'portal-starred-repos';

const loadStarredRepos = (): Set<string> => {
  try {
    return new Set(JSON.parse(localStorage.getItem(STARRED_REPOS_KEY) || '[]'));
  } catch { return new Set(); }
};

const saveStarredRepos = (names: Set<string>) => {
  localStorage.setItem(STARRED_REPOS_KEY, JSON.stringify([...names]));
};

/** Engine in flight — demo overlay. Empty so quality data stays the source of truth. */
const SCANNING_REPOS = new Set<string>();

/** Develop list: score + findings · time · SHA. Open for severity. */
function QualityScoreCell({ repoName }: { repoName: string }) {
  const navigate = useNavigate();
  const { experience } = useNavIaModel();
  const quality = getProjectQuality(repoName);

  const viewScanHistory = () => {
    const qs = new URLSearchParams({ repo: repoName });
    navigate(`${scansListPath(experience)}?${qs.toString()}`);
  };

  const startScan = () => {
    const qs = new URLSearchParams({ from: 'list' });
    navigate(
      `/self-service/apme/remediate/${encodeURIComponent(repoName)}?${qs.toString()}`,
    );
  };

  return (
    <Box style={{ width: '100%', minWidth: 0, overflow: 'hidden' }}>
    <HealthScorePopover
      repoName={repoName}
      quality={quality}
      scanning={SCANNING_REPOS.has(repoName)}
      showScanMeta
      onStartScan={quality ? startScan : undefined}
      onViewLastScan={quality ? viewScanHistory : undefined}
    />
    </Box>
  );
}

function QualityFindingsCell({ repoName }: { repoName: string }) {
  const theme = useTheme();
  const isDark = theme.palette.type === 'dark';
  const navigate = useNavigate();
  const { experience } = useNavIaModel();

  const quality = getProjectQuality(repoName);
  const scanning = SCANNING_REPOS.has(repoName);

  const openLastScan = (category?: string) => {
    const scanId = quality?.latestScan.scanId;
    if (!scanId) {
      navigate(`/self-service/repositories/${encodeURIComponent(repoName)}`);
      return;
    }
    navigate(
      scanSnapshotPath(experience, scanId, {
        repo: repoName,
        ...(category ? { category: category as ApmeRuleCategory } : {}),
      }),
    );
  };

  const openRemediation = () => {
    const qs = new URLSearchParams({ from: 'list', resume: '1' });
    navigate(
      `/self-service/apme/remediate/${encodeURIComponent(repoName)}?${qs.toString()}`,
    );
  };

  if (scanning) {
    return (
      <Chip
        size="small"
        label="Scanning"
        style={{
          fontSize: 11,
          height: 20,
          backgroundColor: `${statusColors.info}15`,
          color: statusColors.info,
          fontWeight: 500,
        }}
      />
    );
  }

  if (!quality) {
    return (
      <Typography variant="body2" color="textSecondary" style={{ fontSize: 12 }}>
        Not scanned
      </Typography>
    );
  }

  const total = quality.totalViolations;
  const breakdown = quality.severityBreakdown;
  const lastScanned = quality.lastScannedAt;
  const remStatus = quality.remediationStatus;
  const compatCount = getProjectCompatibilityCount(repoName);
  const live = remStatus === 'in-progress' || remStatus === 'proposals-ready';

  const findingsChip =
    total === 0 ? (
      <Typography
        variant="body2"
        style={{ fontSize: 12, color: statusColors.success, fontWeight: 500 }}
      >
        Clean
      </Typography>
    ) : (
      (() => {
        const highest: SeverityClass =
          breakdown.critical > 0
            ? 'critical'
            : breakdown.high > 0
              ? 'high'
              : breakdown.medium > 0
                ? 'medium'
                : 'low';
        const highestCount = breakdown[highest];
        const color = SEVERITY_COLORS[highest];
        return (
          <Tooltip
            title={lastScanned ? `Last scanned ${lastScanned}` : ''}
            arrow
            disableHoverListener={!lastScanned}
          >
            <Box display="flex" alignItems="center" style={{ gap: 6 }}>
              <Chip
                size="small"
                label={`${highestCount} ${highest}`}
                style={{
                  fontSize: 11,
                  height: 20,
                  backgroundColor: `${color}18`,
                  color,
                  fontWeight: 600,
                  cursor: 'pointer',
                }}
              />
              {total > highestCount && (
                <Typography
                  variant="body2"
                  color="textSecondary"
                  style={{ fontSize: 11 }}
                >
                  +{total - highestCount}
                </Typography>
              )}
            </Box>
          </Tooltip>
        );
      })()
    );

  return (
    <Box display="flex" alignItems="center" style={{ gap: 8, flexWrap: 'wrap' }}>
      <Box
        display="flex"
        alignItems="center"
        style={{ cursor: 'pointer' }}
        onClick={e => {
          e.stopPropagation();
          openLastScan();
        }}
      >
        {findingsChip}
      </Box>
      {compatCount > 0 && (
        <Chip
          size="small"
          label="Version update"
          icon={
            <WarningIcon
              style={{
                fontSize: 11,
                color: isDark ? '#fbbf24' : '#92400e',
              }}
            />
          }
          onClick={e => {
            e.stopPropagation();
            openLastScan('aap-compatibility');
          }}
          style={{
            fontSize: 10,
            height: 18,
            fontWeight: 600,
            backgroundColor: isDark ? 'rgba(234,179,8,0.12)' : '#fef9c3',
            color: isDark ? '#fbbf24' : '#92400e',
            cursor: 'pointer',
          }}
        />
      )}
      {live && (
        <Typography
          component="button"
          onClick={e => {
            e.stopPropagation();
            openRemediation();
          }}
          style={{
            fontSize: 11,
            fontWeight: 600,
            color: statusColors.info,
            background: 'none',
            border: 'none',
            padding: 0,
            cursor: 'pointer',
          }}
        >
          Remediation in progress
        </Typography>
      )}
      {remStatus === 'pr-open' && (
        <Typography
          component="button"
          onClick={e => {
            e.stopPropagation();
            if (quality.remediationPrUrl) {
              window.open(quality.remediationPrUrl, '_blank', 'noopener,noreferrer');
              return;
            }
            openLastScan();
          }}
          style={{
            fontSize: 11,
            fontWeight: 600,
            color: '#2E8440',
            background: 'none',
            border: 'none',
            padding: 0,
            cursor: 'pointer',
          }}
        >
          Pull request open
        </Typography>
      )}
    </Box>
  );
}

export const GitRepositoriesContent = () => {
  const classes = useStyles();
  const theme = useTheme();
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const { hasRole } = useUserRoleContext();
  const { experience } = useNavIaModel();
  const qualityScoreOnList = isDevelopExperience(experience);
  const [repos, setRepos] = useState<GitRepository[]>(() => {
    const stored = loadStarredRepos();
    return GIT_REPOSITORIES.map(r => ({
      ...r,
      starred: stored.has(r.name) ? true : r.starred,
    }));
  });
  const [searchText, setSearchText] = useState('');
  const [filters, setFilters] = useState<ActiveFilters>(() => ({
    ...DEFAULT_FILTERS,
    quality: parseQualityParam(searchParams.get('quality')),
  }));

  const applyFilters = useCallback(
    (next: ActiveFilters) => {
      setFilters(next);
      const params = new URLSearchParams(searchParams);
      if (next.quality === 'all') params.delete('quality');
      else params.set('quality', next.quality);
      setSearchParams(params, { replace: true });
    },
    [searchParams, setSearchParams],
  );


  const toggleStar = useCallback((name: string) => {
    setRepos(prev => {
      const updated = prev.map(r => (r.name === name ? { ...r, starred: !r.starred } : r));
      const starredNames = new Set(updated.filter(r => r.starred).map(r => r.name));
      saveStarredRepos(starredNames);
      return updated;
    });
  }, []);

  const deleteProject = useCallback((name: string) => {
    setRepos(prev => prev.filter(r => r.name !== name));
  }, []);

  const clearFilter = useCallback(
    (key: keyof ActiveFilters) => {
      applyFilters({ ...filters, [key]: 'all' });
    },
    [applyFilters, filters],
  );

  const clearAllFilters = useCallback(() => {
    applyFilters({ ...DEFAULT_FILTERS });
  }, [applyFilters]);

  const filteredRepos = useMemo(() => {
    let result = repos;
    if (searchText) {
      const lower = searchText.toLowerCase();
      result = result.filter(r =>
        r.name.toLowerCase().includes(lower) || r.org.toLowerCase().includes(lower),
      );
    }
    if (filters.provider !== 'all') {
      result = result.filter(r => r.provider === filters.provider);
    }
    if (filters.quality === 'recent') {
      result = result.filter(r => {
        const q = getProjectQuality(r.name);
        return Boolean(q && isWithinQualityWindow(q.lastScannedAt));
      });
    } else if (filters.quality === 'scanned') {
      result = result.filter(r => Boolean(getProjectQuality(r.name)));
    } else if (filters.quality === 'findings') {
      result = result.filter(r => (getProjectViolationCount(r.name) ?? 0) > 0);
    } else if (
      filters.quality !== 'all' &&
      filters.quality !== 'findings' &&
      filters.quality !== 'scanned' &&
      filters.quality !== 'recent'
    ) {
      const sev = filters.quality;
      result = result.filter(
        r => (getProjectSeverityBreakdown(r.name)?.[sev] ?? 0) > 0,
      );
    }
    return result;
  }, [repos, searchText, filters]);

  if (repos.length === 0) {
    return (
      <EmptyStateLayout
        title="No repositories discovered"
        description="Connect a Git source in the Connections page to discover repositories containing Ansible automation content. The portal will scan for playbooks, roles, collections, and execution environments."
        illustration={<RepositoriesIllustration />}
      />
    );
  }

  const columns: TableColumn<GitRepository>[] = [
    {
      title: 'Repository',
      field: 'name',
      width: '36%',
      render: (row: GitRepository) => (
        <Box display="flex" alignItems="center" style={{ gap: 8, minWidth: 0 }}>
          {row.provider === 'github' ? (
            <GitHubIcon className={classes.providerIcon} />
          ) : (
            <GitLabIcon />
          )}
          <Link
            className={classes.repoLink}
            onClick={(e: React.MouseEvent) => {
              e.stopPropagation();
              navigate(`/self-service/repositories/${row.name}`);
            }}
          >
            {row.org}/{row.name}
          </Link>
        </Box>
      ),
    },
    qualityScoreOnList
      ? {
          title: (
            <Box display="flex" alignItems="center" style={{ gap: 4, whiteSpace: 'nowrap' }}>
              Health
              <Tooltip
                title={HEALTH_SCORE_HINT}
                arrow
              >
                <HelpOutlineIcon style={{ fontSize: 14, color: theme.palette.text.disabled, cursor: 'help' }} />
              </Tooltip>
            </Box>
          ) as unknown as string,
          width: '28%',
          customSort: (a: GitRepository, b: GitRepository) => {
            const rankOf = (r: GitRepository) => {
              if (SCANNING_REPOS.has(r.name)) return -2;
              const score = getProjectHealthScore(r.name);
              if (score === undefined) return -1;
              return score;
            };
            return rankOf(a) - rankOf(b);
          },
          render: (row: GitRepository) => <QualityScoreCell repoName={row.name} />,
          cellStyle: {
            overflow: 'hidden',
          },
        }
      : {
          title: (
            <Box display="flex" alignItems="center" style={{ gap: 4 }}>
              Findings
              <Tooltip
                title="Content quality findings for this repository. Open Content quality for detail."
                arrow
              >
                <HelpOutlineIcon style={{ fontSize: 14, color: theme.palette.text.disabled, cursor: 'help' }} />
              </Tooltip>
            </Box>
          ) as unknown as string,
          width: '28%',
          customSort: (a: GitRepository, b: GitRepository) => {
            const SEVERITY_RANK: Record<string, number> = {
              critical: 4,
              high: 3,
              medium: 2,
              low: 1,
            };
            const rankOf = (r: GitRepository) => {
              if (SCANNING_REPOS.has(r.name)) return 500;
              const bd = getProjectSeverityBreakdown(r.name);
              if (!bd) return -1;
              const total = getProjectViolationCount(r.name) ?? 0;
              if (total === 0) return 0;
              const highest =
                bd.critical > 0
                  ? 'critical'
                  : bd.high > 0
                    ? 'high'
                    : bd.medium > 0
                      ? 'medium'
                      : 'low';
              return SEVERITY_RANK[highest] * 100 + total;
            };
            return rankOf(a) - rankOf(b);
          },
          render: (row: GitRepository) => <QualityFindingsCell repoName={row.name} />,
        },
    {
      title: (
        <Box display="flex" alignItems="center" style={{ gap: 4 }}>
          Content
          <Tooltip title="Automation content discovered in this repository: playbooks, roles, collection dependencies, and execution environments." arrow>
            <HelpOutlineIcon style={{ fontSize: 14, color: theme.palette.text.disabled, cursor: 'help' }} />
          </Tooltip>
        </Box>
      ) as unknown as string,
      width: '22%',
      sorting: false,
      render: (row: GitRepository) => <ResourceBadges resources={row.resources} repoName={row.name} />,
    },
    {
      title: '',
      width: '10%',
      sorting: false,
      cellStyle: { textAlign: 'right' as const, paddingRight: 8 },
      headerStyle: { textAlign: 'right' as const, paddingRight: 8 },
      render: (row: GitRepository) => (
        <Box className={classes.actionsCell}>
          {isDevSpacesConnected() && hasRole('developer') && (
            <Tooltip title="Edit in Dev Spaces" arrow>
              <IconButton
                size="small"
                onClick={(e) => {
                  e.stopPropagation();
                  window.open(`${DEVSPACES_BASE_URL}/#${row.url}/tree/${row.branch}`, '_blank');
                }}
              >
                <CodeIcon fontSize="small" />
              </IconButton>
            </Tooltip>
          )}
          <IconButton size="small" onClick={(e) => { e.stopPropagation(); toggleStar(row.name); }}>
            {row.starred ? (
              <StarIcon style={{ color: statusColors.star }} />
            ) : (
              <StarBorderIcon />
            )}
          </IconButton>
          <RowActionsMenu repo={row} onDelete={deleteProject} />
        </Box>
      ),
    },
  ];

  const filterLabels: { key: keyof ActiveFilters; label: string; value: string }[] = [];
  if (filters.provider !== 'all') {
    filterLabels.push({ key: 'provider', label: 'Provider', value: filters.provider === 'github' ? 'GitHub' : 'GitLab' });
  }
  if (filters.quality !== 'all') {
    filterLabels.push({
      key: 'quality',
      label: 'Quality',
      value: QUALITY_FILTER_LABEL[filters.quality],
    });
  }

  return (
    <Box>
      <Box className={classes.filterBand}>
      <Box className={classes.toolbar}>
        <TextField
          className={classes.searchField}
          placeholder="Search repositories"
          variant="outlined"
          size="small"
          value={searchText}
          onChange={e => setSearchText(e.target.value)}
          inputProps={{ 'aria-label': 'Search repositories' }}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <SearchIcon color="disabled" fontSize="small" />
              </InputAdornment>
            ),
            endAdornment: searchText ? (
              <InputAdornment position="end">
                <IconButton size="small" onClick={() => setSearchText('')} aria-label="Clear search">
                  <ClearIcon fontSize="small" />
                </IconButton>
              </InputAdornment>
            ) : null,
          }}
        />
        <FormControl
          variant="outlined"
          size="small"
          className={classes.providerFilter}
        >
          <InputLabel id="git-repos-provider-label">Provider</InputLabel>
          <Select
            labelId="git-repos-provider-label"
            label="Provider"
            value={filters.provider}
            onChange={e =>
              applyFilters({
                ...filters,
                provider: e.target.value as ProviderFilter,
              })
            }
          >
            <MenuItem value="all">All</MenuItem>
            <MenuItem value="github">GitHub</MenuItem>
            <MenuItem value="gitlab">GitLab</MenuItem>
          </Select>
        </FormControl>
      </Box>

      {hasActiveFilters(filters) && (
        <Box className={classes.activeFiltersRow}>
          <Typography variant="body2" color="textSecondary" style={{ fontSize: 12 }}>
            Active filters:
          </Typography>
          {filterLabels.map(f => (
            <Chip
              key={f.key}
              label={`${f.label}: ${f.value}`}
              size="small"
              onDelete={() => clearFilter(f.key)}
              deleteIcon={<CancelIcon style={{ fontSize: 16 }} />}
              className={classes.activeChip}
              color="primary"
              variant="outlined"
            />
          ))}
          <Button size="small" onClick={clearAllFilters} style={{ textTransform: 'none', fontSize: 12 }}>
            Clear all
          </Button>
        </Box>
      )}
      </Box>

      <Box className={classes.tableHost}>
      <Table<GitRepository>
        columns={columns}
        data={filteredRepos}
        options={{
          paging: true,
          pageSize: 10,
          pageSizeOptions: [5, 10, 20],
          emptyRowsWhenPaging: false,
          search: false,
          toolbar: false,
          sorting: true,
          padding: 'dense',
          rowStyle: { cursor: 'pointer' },
        }}
        emptyContent={
          <Box py={4} textAlign="center">
            <Typography color="textSecondary">
              No repositories match these filters.
            </Typography>
          </Box>
        }
        style={{ width: '100%', overflowX: 'hidden' }}
        onRowClick={(_event, rowData) => {
          if (rowData) {
            const row = rowData as GitRepository;
            navigate(`/self-service/repositories/${row.name}`);
          }
        }}
      />
      </Box>
    </Box>
  );
};
